:"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/homeowner-claim-valuation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Claims","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/commercial-condo-hoa-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/roof-hail-claim-valuation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind, Microburst & Tornado Damage","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/wind-microburst-tornado-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane & Tropical Storm Claims","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/hurricane-tropical-storm-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage & Leak Claims","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/water-leak-sewer-backup-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam, Snow Load & Frozen Pipe Claims","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/ice-dam-freeze-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/fire-smoke-claim-valuation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/claim-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://rhodeislandinsuranceappraiser.com/claim-valuation-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal provision","Hurricane deductibles","Wind and flood damage","Ice dam claims","Property claim estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://rhodeislandinsuranceappraiser.com/#website","url":"https://rhodeislandinsuranceappraiser.com/","name":"Rhode Island Insurance Appraiser","publisher":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#webpage","url":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/","name":"Insurance Appraisal Questions | Rhode Island FAQ","description":"Answers to Rhode Island insurance appraisal questions by topic: the basics, when it fits, costs and timing, and state-specific rules.","inLanguage":"en-US","isPartOf":{"@id":"https://rhodeislandinsuranceappraiser.com/#website"},"about":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"publisher":{"@id":"https://rhodeislandinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#primaryimage","url":"https://rhodeislandinsuranceappraiser.com/assets/img/photos/consultation-table.webp","contentUrl":"https://rhodeislandinsuranceappraiser.com/assets/img/photos/consultation-table.webp","width":960,"height":640},"breadcrumb":{"@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#breadcrumb"},"mainEntity":{"@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#faqpage"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://rhodeislandinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Policyholder questions","item":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/"}],"@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process written into most property policies for settling disagreements about the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and any two of the three can sign a binding award on the amount."}},{"@type":"Question","name":"What does a Rhode Island insurance appraiser do?","acceptedAnswer":{"@type":"Answer","text":"As your appointed appraiser, we inspect, build an independent line-item valuation, work through the differences with the carrier’s appraiser and, if needed, present unresolved items to the umpire."}},{"@type":"Question","name":"Is appraisal the same as mediation?","acceptedAnswer":{"@type":"Answer","text":"No. Mediation is voluntary and non-binding unless you sign a settlement. An appraisal award on the amount of loss is generally binding."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"They’re similar, but appraisal is narrower. It decides the amount of loss, not legal questions like coverage."}},{"@type":"Question","name":"When should I consider appraisal?","acceptedAnswer":{"@type":"Answer","text":"When coverage is accepted, you have the carrier’s itemized estimate and a credible estimate of your own, and the gap between them is meaningful."}},{"@type":"Question","name":"When is appraisal the wrong tool?","acceptedAnswer":{"@type":"Answer","text":"When the claim was denied, when the dispute is about coverage or causation, when the gap is too small to justify fees, or when a deadline is close and you need legal advice."}},{"@type":"Question","name":"Can the insurer demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes. Most policies let either side invoke it."}},{"@type":"Question","name":"Can appraisal handle wind versus flood questions?","acceptedAnswer":{"@type":"Answer","text":"Appraisal under your homeowner policy values the covered loss. Whether damage was caused by wind or flood is usually a causation and coverage question outside appraisal."}},{"@type":"Question","name":"What does appraisal cost?","acceptedAnswer":{"@type":"Answer","text":"Each side pays its own appraiser, and the umpire’s fee is usually split. Fee arrangements vary; ask for one in writing."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"A few weeks for a straightforward residential claim once appraisers are named. Complex or commercial claims can take several months."}},{"@type":"Question","name":"Is your first conversation free?","acceptedAnswer":{"@type":"Answer","text":"Yes. We’ll tell you honestly whether appraisal is likely to help."}},{"@type":"Question","name":"Who regulates insurance in Rhode Island?","acceptedAnswer":{"@type":"Answer","text":"The Rhode Island Department of Business Regulation, through its Insurance Division. It handles consumer complaints and licenses insurers, agents and adjusters."}},{"@type":"Question","name":"What is the Rhode Island FAIR Plan?","acceptedAnswer":{"@type":"Answer","text":"A property insurer of last resort for owners who can’t find coverage in the regular market, often near the coast. FAIR Plan policies have their own terms, including how disputes over the amount of loss are handled."}},{"@type":"Question","name":"Do Rhode Island policies have hurricane deductibles?","acceptedAnswer":{"@type":"Answer","text":"Many do. They’re usually a percentage of dwelling coverage and apply when the storm meets the policy’s trigger. Check your declarations page."}},{"@type":"Question","name":"Does Rhode Island have a bad-faith law?","acceptedAnswer":{"@type":"Answer","text":"Yes. Rhode Island has a statute allowing an insured to bring a claim against an insurer for bad-faith refusal to pay or settle. Whether it applies is a legal question for a Rhode Island attorney; appraisal doesn’t decide it."}},{"@type":"Question","name":"Do you serve the whole state?","acceptedAnswer":{"@type":"Answer","text":"Yes, all 39 cities and towns across Rhode Island’s five counties, including Block Island by arrangement."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"Neither. We provide appraisal, estimating and umpire services. We don’t give legal advice or negotiate claims outside the appraisal process."}},{"@type":"Question","name":"Can you guarantee a result?","acceptedAnswer":{"@type":"Answer","text":"No. No honest appraiser can. We can promise a thorough, documented valuation."}},{"@type":"Question","name":"What should I send first?","acceptedAnswer":{"@type":"Answer","text":"Your declarations page and policy, the carrier’s full estimate, any contractor estimate, photos and the carrier’s letters."}}],"@id":"https://rhodeislandinsuranceappraiser.com/policyholder-questions/#faqpage"}]}</script>
</head>
